CREATE OR REPLACE FUNCTION public.mwd_owner_partner_location_save_demo(p_partner_id uuid, p_display_name text, p_city text, p_currency_code text, p_hours_note text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid;v_id uuid;
BEGIN
 v_actor:=mwd_partners_private.assert_owner();
 IF p_partner_id IS NULL OR p_display_name IS NULL
    OR char_length(btrim(p_display_name)) NOT BETWEEN 2 AND 140
    OR p_city IS NULL OR char_length(btrim(p_city)) NOT BETWEEN 2 AND 100
    OR p_currency_code IS NULL OR p_currency_code !~ '^[A-Z]{3}$'
    OR char_length(coalesce(p_hours_note,'')) > 140 THEN
  RAISE EXCEPTION 'Datos de sucursal no válidos' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM mwd_partners_private.partners p
 WHERE p.id=p_partner_id AND p.review_status<>'archived' FOR UPDATE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Socio no disponible' USING ERRCODE='22023';
 END IF;
 IF p_location_id IS NULL THEN
  INSERT INTO mwd_partners_private.locations(partner_id,display_name,city,currency_code,hours_note,created_by,updated_by)
  VALUES(p_partner_id,btrim(p_display_name),btrim(p_city),p_currency_code,
         nullif(btrim(coalesce(p_hours_note,'')),''),v_actor,v_actor)
  RETURNING id INTO v_id;
 ELSE
  UPDATE mwd_partners_private.locations l
  SET display_name=btrim(p_display_name),city=btrim(p_city),currency_code=p_currency_code,
      hours_note=nullif(btrim(coalesce(p_hours_note,'')),''),
      updated_by=v_actor,updated_at=now()
  WHERE l.id=p_location_id AND l.partner_id=p_partner_id
  RETURNING id INTO v_id;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Sucursal inexistente' USING ERRCODE='22023';
  END IF;
 END IF;
 RETURN jsonb_build_object('id',v_id,'review_status','draft','real_payouts_enabled',false);
END;
$function$
